use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sqlx::PgPool;
use std::collections::HashMap;
use tracing::{info, instrument, span, Level};
use uuid::Uuid;

use llm_governance_common::adapters::change_impact::{
    AffectedSystem, ChangeRequest, ChangeSubjectType, ChangeType, ComplianceImpactStatus,
    ComplianceImplication, CostImplication, HistoricalContext, HistoricalOutcome, ImpactArea,
    ImpactDetail, ImpactLevel, ImpactRecommendation, PolicyImplication, PolicyImplicationType,
    RecommendationPriority, RecommendationType, RiskClassification, RiskIndicator,
    RiskIndicatorCategory, AGENT_ID, AGENT_VERSION,
};
use llm_governance_common::adapters::ruvector::{
    create_decision_event, default_confidence, execution_ref_from_request, ConstraintApplication,
    ConstraintScope, ConstraintType, DataReference, DataReferenceType, DateRange,
    DecisionConfidence, DecisionOutputs, FindingCategory, GovernanceDecisionType,
    GovernanceFinding, GovernanceMetrics, GovernanceSeverity, InvocationSource, TrendDirection,
};
use llm_governance_common::{ApiResponse, AppError, Result};

